package watch

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// OpenCode has no hook config to merge: a plugin file in its plugins
// folder is loaded on start. Rex writes one small generated file there:
// it pipes events to `rex ingest --source opencode`, and before each
// prompt asks it for the pin note (docs/ux.md §7a).

// The plugin's first line says Rex wrote it, and which plugin it is. One
// from before the versions (v1) feeds the feed but never asks for the pin.
// A change OpenCode users should get bumps opencodeVersion, so Harness.Old
// knows the plugin they have.
const (
	opencodeVersion  = 2
	opencodeMarker   = "// generated by rex · plugin v2 — safe to delete"
	opencodeMarkerV1 = "// generated by rex — safe to delete"
)

// openCodeCap is the most of rex's reply the plugin reads (its CAP).
const openCodeCap = 8192

// pluginVersion is the version of the rex plugin data is, read from its
// first line: 1 for one older than the versions, 0 for a file Rex didn't
// write.
func pluginVersion(data []byte) int {
	line, _, _ := bytes.Cut(data, []byte("\n"))
	s := strings.TrimSuffix(string(line), "\r")
	if s == opencodeMarkerV1 {
		return 1
	}
	n, ok := strings.CutPrefix(s, "// generated by rex · plugin v")
	n, end := strings.CutSuffix(n, " — safe to delete")
	v, err := strconv.Atoi(n)
	if !ok || !end || err != nil || v < 2 {
		return 0
	}
	return v
}

// openCodeTypes are the payload types the plugin sends to the feed. Its
// request for the pin note, "context", is no event (ContextEvent).
var openCodeTypes = map[string]bool{
	"chat.message": true, "message.part.updated": true, "session.idle": true, "session.error": true,
	"permission.updated": true, "permission.asked": true, "question.asked": true,
}

// opencodePluginJS is the plugin. It never throws from a hook, and only
// chat.message waits for rex: at most WAIT (1.5 s), for the pin note,
// read up to CAP (8 KB), which it adds to the prompt as one synthetic text
// part (the person isn't shown it, the model is), the only output it sets.
// Only allow-listed fields leave it: no file bodies, diffs, attachments or
// tool output; the prompt's event carries the task and plan the note it
// added names, as rex's reply spelled them (SentPin). A subagent's
// (child) session is agent work: its prompt, replies, thoughts, errors
// and turn end are not sent and its prompts get no note (its tool calls
// are sent), and neither does a prompt with no text of the person's (a
// background task's result is all synthetic).
// The reply is the last text of a turn, sent with session.idle, as Claude
// Code's Stop does; parts older than the plugin (a fork replays history)
// are skipped.
const opencodePluginJS = opencodeMarker + `
// Pipes OpenCode events to rex, and adds the task pinned in Rex to each prompt: https://github.com/luciancheng/rex
import { spawn } from "node:child_process"
const REX = %s
const started = Date.now()
let q = Promise.resolve()
function send(p) {
  let line
  try { line = JSON.stringify(p) + "\n" } catch { return }
  q = q.then(() => new Promise((done) => {
    try {
      const c = spawn(REX, ["ingest", "--source", "opencode"], { stdio: ["pipe", "ignore", "ignore"], windowsHide: true })
      const t = setTimeout(() => { try { c.kill() } catch {} ; done() }, 5000)
      c.on("error", () => { clearTimeout(t); done() })
      c.on("close", () => { clearTimeout(t); done() })
      c.stdin.on("error", () => {})
      c.stdin.end(line)
    } catch { done() }
  })).catch(() => {})
}
// ask is rex's reply for a prompt in dir, or {}: the note on the task
// pinned in Rex, and the task (pin) and plan (pin_plan) it names. It waits
// at most WAIT ms, reads at most CAP bytes, and never rejects. It is not
// queued behind send.
const WAIT = 1500, CAP = 8192
function ask(dir, sessionID) {
  return new Promise((done) => {
    let c, size = 0
    const chunks = []
    const end = (r) => { clearTimeout(t); done(r) }
    const stop = () => { try { c.kill() } catch {} ; end({}) }
    const t = setTimeout(stop, WAIT)
    try {
      c = spawn(REX, ["ingest", "--source", "opencode"], { stdio: ["pipe", "pipe", "ignore"], windowsHide: true })
      c.on("error", () => end({}))
      c.on("close", (code) => end(code === 0 && size <= CAP ? reply(Buffer.concat(chunks).toString("utf8")) : {}))
      c.stdout.on("error", () => {})
      c.stdout.on("data", (d) => { size += d.length; if (size <= CAP) chunks.push(d); else if (size - d.length <= CAP) stop() })
      c.stdin.on("error", () => {})
      c.stdin.end(JSON.stringify({ type: "context", cwd: dir, sessionID }) + "\n")
    } catch { end({}) }
  })
}
const reply = (s) => { try { const r = JSON.parse(s); return r !== null && typeof r === "object" ? r : {} } catch { return {} } }
const str = (v) => (typeof v === "string" ? v : undefined)
// partID is a part id in OpenCode's own shape ("prt_", 12 hex digits of
// time and a counter, 14 random characters) that sorts after every part
// in parts: OpenCode orders a message's parts by id. Past the largest 12
// digits it keeps them, and its last 14 characters sort last.
const B62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
let seq = 0
function partID(parts) {
  let n = (BigInt(Date.now()) * 4096n + BigInt(++seq & 0xfff)) & 0xffffffffffffn
  for (const x of parts) {
    const m = /^prt_([0-9a-f]{12})/.exec(str(x?.id) ?? "")
    if (m && BigInt("0x" + m[1]) >= n) n = BigInt("0x" + m[1]) + 1n
  }
  let r = ""
  for (let i = 0; i < 14; i++) r += B62[Math.floor(Math.random() * 62)]
  if (n > 0xffffffffffffn) { n = 0xffffffffffffn; r = "zzzzzzzzzzzzzz" }
  return "prt_" + n.toString(16).padStart(12, "0") + r
}
const input = (i = {}) => {
  const out = {}
  for (const k of ["filePath", "path", "command", "description", "pattern", "query", "url", "name", "subagent_type"]) if (str(i[k])) out[k] = i[k]
  if (Array.isArray(i.todos)) out.todos = i.todos.map((t) => ({ content: String(t?.content ?? ""), status: str(t?.status) }))
  return out
}
const files = (m) => Array.isArray(m?.files) ? m.files.map((f) => ({ path: str(f?.movePath) || str(f?.filePath), type: str(f?.type) })).filter((f) => f.path) : undefined
const tool = (s = {}) => ({ status: s.status, input: input(s.input), error: str(s.error), files: files(s.metadata), exit: typeof s.metadata?.exit === "number" ? s.metadata.exit : undefined })
export const RexPlugin = async (ctx) => {
  const cwd = ctx?.directory || ctx?.worktree || ""
  const roles = new Map(), seen = new Set(), children = new Set(), last = new Map()
  return {
    event: async ({ event }) => {
      try {
        const p = event?.properties ?? {}
        switch (event?.type) {
          case "session.created": case "session.updated":
            if (p.info?.id && p.info.parentID) children.add(p.info.id)
            return
          case "message.updated":
            if (p.info?.id) roles.set(p.info.id, p.info.summary || p.info.mode === "compaction" ? "summary" : p.info.role)
            return
          case "message.part.updated": {
            const part = p.part
            if (!part) return
            const end = part.time?.end ?? part.state?.time?.end
            if (typeof end === "number" && end < started - 5000) return
            if (part.type === "tool") {
              const st = part.state?.status, key = part.callID + ":" + st
              if (["running", "completed", "error"].includes(st) && !seen.has(key)) {
                seen.add(key)
                send({ type: event.type, cwd, sessionID: part.sessionID, part: { type: "tool", tool: part.tool, callID: part.callID, state: tool(part.state) } })
              }
              return
            }
            if (children.has(part.sessionID) || !part.time?.end || part.synthetic || part.ignored || roles.get(part.messageID) !== "assistant" || seen.has(part.id)) return
            seen.add(part.id)
            if (part.type === "reasoning") send({ type: event.type, cwd, sessionID: part.sessionID, part: { type: "reasoning", text: str(part.text) } })
            if (part.type === "text") last.set(part.sessionID, str(part.text))
            return
          }
          case "session.idle": {
            if (children.has(p.sessionID)) return
            const text = last.get(p.sessionID)
            last.delete(p.sessionID)
            send({ type: event.type, cwd, sessionID: p.sessionID, text })
            return
          }
          case "session.error":
            if (children.has(p.sessionID)) return
            send({ type: event.type, cwd, sessionID: p.sessionID, error: { name: str(p.error?.name), message: str(p.error?.data?.message) ?? str(p.error?.message) } })
            return
          case "permission.updated": case "permission.asked":
            send({ type: event.type, cwd, properties: { title: str(p.title), type: str(p.type), permission: str(p.permission), patterns: Array.isArray(p.patterns) ? p.patterns.filter(str) : undefined, sessionID: str(p.sessionID) } })
            return
          case "question.asked":
            send({ type: event.type, cwd, properties: { questions: Array.isArray(p.questions) ? p.questions.map((x) => ({ question: str(x?.question), header: str(x?.header) })) : undefined } })
            return
        }
      } catch {}
    },
    "chat.message": async (inp, output) => {
      try {
        const sessionID = inp?.sessionID
        if (children.has(sessionID)) return
        const parts = Array.isArray(output?.parts) ? output.parts : []
        const text = parts.filter((x) => x?.type === "text" && !x.synthetic && !x.ignored).map((x) => x.text).join("\n").trim()
        if (!text) return
        const p = { type: "chat.message", cwd, sessionID, text }
        try {
          const r = await ask(cwd, sessionID)
          const note = str(r.note)?.trim(), message = output.message
          if (note && str(message?.id)) {
            parts.push({ id: partID(parts), messageID: message.id, sessionID: str(message.sessionID) ?? sessionID, type: "text", text: note, synthetic: true })
            p.pin = str(r.pin)
            p.pin_plan = str(r.pin_plan)
          }
        } catch {}
        send(p)
      } catch {}
    },
  }
}
`

// opencodeDir is OpenCode's config folder: $XDG_CONFIG_HOME/opencode, else
// ~/.config/opencode (on every OS).
func opencodeDir(home string) string {
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		return filepath.Join(x, "opencode")
	}
	return filepath.Join(home, ".config", "opencode")
}

func opencodePlugin(home string) string { return filepath.Join(opencodeDir(home), "plugins", "rex.js") }

func opencodeSource(exe string) []byte {
	q, _ := json.Marshal(exe)
	return []byte(fmt.Sprintf(opencodePluginJS, q))
}

// installOpenCode writes the plugin atomically, over an older one Rex
// wrote too. A rex.js that Rex didn't write is left alone, and so is a
// newer Rex's: replacing it would lose what the newer plugin does.
func installOpenCode(path string, out io.Writer) error {
	want := opencodeSource(rexExecutable())
	if fi, err := os.Lstat(path); err == nil && fi.Mode()&os.ModeSymlink != 0 {
		resolved, err := filepath.EvalSymlinks(path)
		if err != nil {
			return fmt.Errorf("%s is a link to a file that isn't there; fix or remove it first", path)
		}
		path = resolved // a dotfiles symlink stays a symlink
	}
	have, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return err // can't tell whose it is, so it stays
	}
	if err == nil && pluginVersion(have) == 0 {
		return fmt.Errorf("%s exists and Rex didn't write it; move it to install the rex plugin", path)
	}
	if v := pluginVersion(have); err == nil && v > opencodeVersion {
		fmt.Fprintf(out, "kept the opencode plugin at %s: a newer Rex wrote it (plugin v%d; this Rex has v%d)\n", path, v, opencodeVersion)
		return nil
	}
	if err == nil && bytes.Equal(have, want) {
		fmt.Fprintf(out, "opencode plugin already installed at %s\n", path)
	} else {
		if err := writeFileAtomic(path, want, 0o644); err != nil {
			return err
		}
		fmt.Fprintf(out, "installed opencode plugin at %s (restart OpenCode to load it)\n", path)
	}
	fmt.Fprintln(out, "opencode: before each prompt the plugin also adds the task pinned in this repo's Rex plan, if one is, to the agent's context")
	fmt.Fprintf(out, "feed: %s\n", DefaultEventPath())
	return nil
}

func uninstallOpenCode(path string, out io.Writer) error {
	have, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		fmt.Fprintf(out, "opencode: no rex plugin at %s\n", path)
		return nil
	}
	if err != nil {
		return err
	}
	if pluginVersion(have) == 0 {
		return fmt.Errorf("%s wasn't written by Rex; leaving it", path)
	}
	target := ""
	if fi, err := os.Lstat(path); err == nil && fi.Mode()&os.ModeSymlink != 0 {
		target, _ = filepath.EvalSymlinks(path)
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	fmt.Fprintf(out, "removed the rex plugin from %s\n", path)
	if target != "" {
		fmt.Fprintf(out, "it was a link; the file it pointed to, %s, is kept\n", target)
	}
	return nil
}

// writeFileAtomic writes data to path through a temp file in the same
// folder, so OpenCode never loads half a plugin. Windows refuses to
// replace a file another process holds open (Rex reads the plugin every
// few seconds while a plan is open, for feed health), so a failed rename
// writes it in place instead.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".rex-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), mode); err != nil {
		return err
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		// Not atomic, as UpdateJSONFile's fallback isn't, but written.
		if werr := os.WriteFile(path, data, mode); werr != nil {
			return err
		}
	}
	return nil
}

// openCodeInstalled is the version of the rex plugin installed for home,
// or 0 for none.
func openCodeInstalled(home string) int {
	data, err := os.ReadFile(opencodePlugin(home))
	if err != nil {
		return 0
	}
	return pluginVersion(data)
}

// openCodeReply is rex's reply to the plugin's context request: one JSON
// object with the note and what it names, the task (pin, none for a plan
// with no tasks yet) and the plan (pin_plan) as the file spells them, so
// the plugin never reads them back from the note's wording. A reply over
// the plugin's CAP, which it would drop whole, goes without them.
func openCodeReply(note string, carried map[string]any) []byte {
	reply := map[string]any{"note": note}
	for _, k := range []string{"pin", "pin_plan"} {
		if v, ok := carried[k]; ok {
			reply[k] = v
		}
	}
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	if enc.Encode(reply) != nil {
		return nil
	}
	if b.Len() > openCodeCap && len(reply) > 1 {
		return openCodeReply(note, nil)
	}
	return b.Bytes()
}

// SentPin is what the OpenCode plugin says the prompt in payload, its
// chat.message, carried: the plan (pin_plan) and task (pin, none for a
// plan with no tasks yet) the note it added names, copied from rex's
// reply to its context request, or nil when it added no note. Only an
// explicit --source opencode counts.
func SentPin(payload map[string]any, source string) map[string]any {
	if source != "opencode" || strField(payload, "type") != "chat.message" || strField(payload, "agent_id") != "" {
		return nil
	}
	rel, _ := payload["pin_plan"].(string)
	id, ok := payload["pin"].(string)
	if rel == "" || !ok && payload["pin"] != nil || len(rel)+len(id) > openCodeCap {
		return nil
	}
	sent := map[string]any{"pin_plan": rel}
	if id != "" {
		sent["pin"] = id
	}
	return sent
}

// MapOpenCode maps one payload from the rex plugin.
func MapOpenCode(payload map[string]any) *Event {
	cwd := strField(payload, "cwd")
	event := func(kind, text string, meta map[string]any) *Event {
		if strings.TrimSpace(text) == "" {
			return nil
		}
		ev := NewEvent("opencode", kind, text, meta)
		return &ev
	}
	abs := func(p string) string {
		if p != "" && !filepath.IsAbs(p) && cwd != "" {
			return filepath.Join(cwd, p)
		}
		return p
	}
	switch strField(payload, "type") {
	case "chat.message":
		// What the prompt carried (meta pin and pin_plan) is ingest's to
		// stamp, for an explicit --source opencode only (SentPin,
		// docs/ux.md §7a).
		return event("user", strings.TrimSpace(strField(payload, "text")), nil)
	case "context":
		return nil // the plugin asking for the pin note (ContextEvent): never in the feed
	case "message.part.updated":
		part := asDict(payload["part"])
		switch strField(part, "type") {
		case "reasoning":
			return event("thought", strings.TrimSpace(strField(part, "text")), nil)
		case "tool":
			return openCodeTool(part, abs, event)
		}
	case "session.idle":
		// The turn's last text is its reply, sent with the idle.
		if text, _ := payload["text"].(string); strings.TrimSpace(text) != "" {
			return event("text", strings.TrimSpace(text), nil)
		}
		return event("idle", "turn completed", nil)
	case "session.error":
		e := asDict(payload["error"])
		name, _ := e["name"].(string)
		msg, _ := e["message"].(string)
		if msg == "" {
			msg, _ = asDict(e["data"])["message"].(string)
		}
		switch name {
		case "MessageAbortedError":
			return event("idle", "turn interrupted", map[string]any{"status": "aborted"})
		case "ContextOverflowError":
			return nil // OpenCode compacts and carries on
		}
		if msg == "" {
			msg = name
		}
		if msg == "" {
			return event("error", "session error", nil) // OpenCode's error is optional
		}
		return event("error", "session error: "+firstLine(msg), nil)
	case "permission.updated", "permission.asked":
		props := asDict(payload["properties"])
		text := strField(props, "title")
		if text == "" {
			var patterns []string
			if list, ok := props["patterns"].([]any); ok {
				for _, p := range list {
					if s, ok := p.(string); ok {
						patterns = append(patterns, s)
					}
				}
			}
			text = strings.TrimSpace(strField(props, "permission") + " " + strField(props, "type"))
			if len(patterns) > 0 {
				text += ": " + strings.Join(patterns, ", ")
			}
		}
		return event("question", "permission: "+text, nil)
	case "question.asked":
		props := asDict(payload["properties"])
		return event("question", toolText("question", props), toolMeta("question", ""))
	}
	return nil
}

func openCodeTool(part map[string]any, abs func(string) string, event func(string, string, map[string]any) *Event) *Event {
	tool := strField(part, "tool")
	if tool == "question" && strField(asDict(part["state"]), "status") == "running" {
		return nil // question.asked carries the question; its answer still ends the ask
	}
	state := asDict(part["state"])
	input := asDict(state["input"])
	status := strField(state, "status")
	var paths []any
	if p := abs(strField(input, "filePath")); p != "" {
		paths = append(paths, p)
	}
	deleted := false
	if files, ok := state["files"].([]any); ok {
		for _, f := range files {
			if v := asDict(f); v != nil {
				if p, _ := v["path"].(string); p != "" {
					paths = append(paths, abs(p))
					deleted = deleted || (len(paths) == 1 && v["type"] == "delete")
				}
			}
		}
	}
	if len(paths) > 1 && paths[0] == paths[1] {
		paths = paths[1:]
	}
	first := ""
	if len(paths) > 0 {
		first = paths[0].(string)
	}
	meta := toolMeta(tool, first)
	if len(paths) > 1 {
		meta["paths"] = paths
	}
	cmd := strings.TrimSpace(asCommand(input["command"]))
	edit := IsFileEditTool(tool) || tool == "apply_patch"
	switch status {
	case "running":
		switch {
		case IsShellTool(tool):
			meta["command"] = cmd
			return event("command", cmd, meta)
		case first != "":
			return event(toolKind(tool), tool+" "+first, meta)
		}
		return event(toolKind(tool), openCodeToolText(tool, input), meta)
	case "completed":
		switch {
		case edit && first != "":
			meta["ok"] = true
			verb := "wrote "
			if deleted {
				verb = "deleted "
			}
			return event("result", verb+first, meta)
		case IsShellTool(tool):
			meta["command"] = cmd
			if exit, ok := state["exit"].(float64); ok {
				meta["ok"] = exit == 0 // OpenCode's bash says its exit code
			}
			return event("result", "ran "+cmd, meta)
		}
		return event("result", tool, meta)
	case "error":
		meta["ok"] = false
		text := tool + " failed"
		if IsShellTool(tool) && cmd != "" {
			meta["command"] = cmd
			text += " · " + cmd
		} else if first != "" {
			text += " · " + first
		}
		if e := strings.TrimSpace(strField(state, "error")); e != "" {
			text += ": " + firstLine(e)
		}
		return event("error", text, meta)
	}
	return nil
}

// openCodeToolText is a short line for one of OpenCode's own tools, never
// a JSON dump or a whole subagent prompt.
func openCodeToolText(tool string, input map[string]any) string {
	switch tool {
	case "todowrite":
		return claudeToolText("TodoWrite", input)
	case "task":
		if d := firstLine(strField(input, "description")); d != "" {
			return "task " + d
		}
		return "task"
	case "skill":
		return strings.TrimSpace("skill " + strField(input, "name"))
	}
	return claudeToolText(tool, input)
}

func init() {
	registerHarness(Harness{
		Name:    "opencode",
		Label:   "OpenCode",
		Config:  opencodePlugin,
		Present: func(home string) bool { return dirExists(opencodeDir(home)) },
		Wired:   func(home string) bool { return openCodeInstalled(home) > 0 },
		Old:     func(home string) bool { v := openCodeInstalled(home); return v > 0 && v < opencodeVersion },
		Install: func(home string, out io.Writer) error {
			if !dirExists(opencodeDir(home)) {
				fmt.Fprintf(out, "opencode: OpenCode isn't set up here (no %s); nothing changed\n", opencodeDir(home))
				return nil
			}
			return installOpenCode(opencodePlugin(home), out)
		},
		Uninstall: func(home string, out io.Writer) error { return uninstallOpenCode(opencodePlugin(home), out) },
	})
}
